def run(path, pairs):
    s = open(path, encoding='utf-8').read()
    shutil.copy(path, path + '.bak')
    miss = []
    for a, b in sorted(pairs, key=lambda p: -len(p[0])):
        if a == b: continue
        if a in s: s = s.replace(a, b)
        else: miss.append(a)
    open(path, 'w', encoding='utf-8').write(s)
    print(path, '— не знайдено фраз:', len(miss))
    for m in miss: print('  ?', m[:70])
    for i, l in enumerate(s.splitlines(), 1):
        if re.search('[ыэъёЫЭЪЁ]', l): print(f'  рос. залишок {i}:', l.strip()[:100])

for p in sys.argv[1:]:
    run(p, DBG if 'debug' in p else IDX)
